import { defineConfig } from 'vite';
import { resolve } from 'node:path';

// Demo-only bundling. The library itself (src/) ships as pure TS with zero
// runtime dependencies; vite is only used to serve/build demo/.
// parity.html is generated by demo/generate-parity.py and committed; its
// VIPS-side JPEGs (demo/parity/, git-ignored) are built by `npm run parity`.
// The WebGL side renders live via ../src. Both pages are build entries.
export default defineConfig({
  root: resolve(__dirname, 'demo'),
  build: {
    outDir: resolve(__dirname, 'dist-demo'),
    emptyOutDir: true,
    rollupOptions: {
      input: {
        main: resolve(__dirname, 'demo/index.html'),
        parity: resolve(__dirname, 'demo/parity.html'),
      },
    },
  },
});
